using System;
using System.Collections.Generic;
using Framework.Grid;
using Framework.Movement;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// グリッド経路追従システムの動作を検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class GridPathFollowerTest : MonoBehaviour
    {
        [Header("テスト設定")]

        [SerializeField]
        [Tooltip("開始時にテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]

        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 予定されているテスト件数。
        /// </summary>
        private const int ExpectedTestCount = 53;

        /// <summary>
        /// テスト用グリッドオブジェクト。
        /// </summary>
        private GameObject gridObject;

        /// <summary>
        /// テスト用移動オブジェクト。
        /// </summary>
        private GameObject movementObject;

        /// <summary>
        /// テスト用座標変換コンポーネント。
        /// </summary>
        private GridCoordinateConverter converter;

        /// <summary>
        /// テスト用移動制御。
        /// </summary>
        private GridMovementController movement;

        /// <summary>
        /// テスト対象の経路追従システム。
        /// </summary>
        private GridPathFollower follower;

        /// <summary>
        /// 通行不可能なセルの集合。
        /// </summary>
        private readonly HashSet<Vector2Int> blockedCells =
            new HashSet<Vector2Int>();

        /// <summary>
        /// テスト用の開始位置。
        /// </summary>
        private readonly Vector2Int startCell =
            new Vector2Int(1, 1);

        /// <summary>
        /// 開始時にテストを実行する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "Play Modeでテストを実行してください。",
                    this);

                return;
            }

            passedCount = 0;
            failedCount = 0;

            try
            {
                Setup();

                TestInitialization();
                TestPathValidation();
                TestFollowing();
                TestPathReplacement();
                TestPauseAndResume();
                TestFailure();
                TestLifecycle();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
            finally
            {
                Cleanup();
            }

            Debug.Log(
                $"【GridPathFollower テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (passedCount == ExpectedTestCount &&
                 failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストがあります。"),
                this);
        }

        /// <summary>
        /// テスト用のグリッドと移動制御を生成する。
        /// </summary>
        private void Setup()
        {
            gridObject =
                new GameObject("PathFollower_Grid_Test");

            var grid =
                gridObject.AddComponent<UnityEngine.Grid>();

            grid.cellSize = new Vector3(1f, 1f, 0f);

            converter =
                gridObject.AddComponent<
                    GridCoordinateConverter>();

            movementObject =
                new GameObject("PathFollower_Movement_Test");

            movement =
                movementObject.AddComponent<
                    GridMovementController>();

            movement.AutoUpdate = false;

            Prepare();
        }

        /// <summary>
        /// 各テストに必要な初期状態を準備する。
        /// </summary>
        private void Prepare()
        {
            follower?.Dispose();

            blockedCells.Clear();

            movement.StopImmediately();

            movement.Resume();

            movement.Initialize(
                converter,
                CanEnterCell,
                startCell);

            // 1秒で1セル移動する設定に統一する。
            movement.MoveSpeed = 1f;

            movement.AutoUpdate = false;

            follower = new GridPathFollower(movement);
        }

        /// <summary>
        /// テスト用セルの通行可能性を判定する。
        /// </summary>
        /// <param name="position">判定対象の座標</param>
        /// <returns>通行可能な場合はtrue</returns>
        private bool CanEnterCell(Vector2Int position)
        {
            return position.x >= 0 &&
                position.x < 7 &&
                position.y >= 0 &&
                position.y < 7 &&
                !blockedCells.Contains(position);
        }

        /// <summary>
        /// 基本テスト用の経路を生成する。
        /// </summary>
        /// <returns>開始位置を含む4セルの経路</returns>
        private List<Vector2Int> CreatePath()
        {
            return new List<Vector2Int>
            {
                new Vector2Int(1, 1),
                new Vector2Int(2, 1),
                new Vector2Int(3, 1),
                new Vector2Int(3, 2)
            };
        }

        /// <summary>
        /// 初期化状態を検証する。
        /// </summary>
        private void TestInitialization()
        {
            Prepare();

            bool statePassed =
                follower.State ==
                GridPathFollowerState.Idle;
            Debug.Assert(statePassed, "初期状態", this);
            Check(statePassed, "初期状態");

            bool movementPassed =
                ReferenceEquals(
                    follower.Movement,
                    movement);
            Debug.Assert(movementPassed, "移動制御の参照", this);
            Check(movementPassed, "移動制御の参照");

            bool emptyPassed =
                !follower.HasPath &&
                follower.Path.Count == 0;
            Debug.Assert(emptyPassed, "初期経路の空状態", this);
            Check(emptyPassed, "初期経路の空状態");

            bool indexPassed =
                follower.CurrentPathIndex == -1;
            Debug.Assert(indexPassed, "初期インデックス", this);
            Check(indexPassed, "初期インデックス");

            bool startPassed =
                follower.PathStartCell == startCell;
            Debug.Assert(startPassed, "探索開始位置", this);
            Check(startPassed, "探索開始位置");

            bool failurePassed =
                follower.LastFailureReason ==
                GridPathFailureReason.None;
            Debug.Assert(failurePassed, "初期失敗理由", this);
            Check(failurePassed, "初期失敗理由");
        }

        /// <summary>
        /// 経路設定時の検証処理を確認する。
        /// </summary>
        private void TestPathValidation()
        {
            Prepare();

            bool nullPassed =
                !follower.TrySetPath(null);
            Debug.Assert(nullPassed, "null経路の拒否", this);
            Check(nullPassed, "null経路の拒否");

            bool emptyPassed =
                !follower.TrySetPath(
                    new List<Vector2Int>());
            Debug.Assert(emptyPassed, "空経路の拒否", this);
            Check(emptyPassed, "空経路の拒否");

            bool startPassed =
                !follower.TrySetPath(
                    new List<Vector2Int>
                    {
                        new Vector2Int(2, 1),
                        new Vector2Int(3, 1)
                    });
            Debug.Assert(startPassed, "不正な開始位置の拒否", this);
            Check(startPassed, "不正な開始位置の拒否");

            bool diagonalPassed =
                !follower.TrySetPath(
                    new List<Vector2Int>
                    {
                        startCell,
                        new Vector2Int(2, 2)
                    });
            Debug.Assert(diagonalPassed, "斜め経路の拒否", this);
            Check(diagonalPassed, "斜め経路の拒否");

            bool jumpPassed =
                !follower.TrySetPath(
                    new List<Vector2Int>
                    {
                        startCell,
                        new Vector2Int(3, 1)
                    });
            Debug.Assert(jumpPassed, "非隣接経路の拒否", this);
            Check(jumpPassed, "非隣接経路の拒否");

            bool duplicatePassed =
                !follower.TrySetPath(
                    new List<Vector2Int>
                    {
                        startCell,
                        startCell
                    });
            Debug.Assert(duplicatePassed, "連続重複セルの拒否", this);
            Check(duplicatePassed, "連続重複セルの拒否");

            blockedCells.Add(new Vector2Int(2, 1));

            bool blockedPassed =
                !follower.TrySetPath(CreatePath());
            Debug.Assert(blockedPassed, "障害セルを含む経路の拒否", this);
            Check(blockedPassed, "障害セルを含む経路の拒否");

            blockedCells.Clear();

            bool singlePassed =
                follower.TrySetPath(
                    new List<Vector2Int> { startCell }) &&
                follower.State ==
                    GridPathFollowerState.Completed &&
                follower.Progress == 1f;
            Debug.Assert(singlePassed, "開始位置のみの経路", this);
            Check(singlePassed, "開始位置のみの経路");

            var sourcePath = CreatePath();

            bool validPassed =
                follower.TrySetPath(sourcePath) &&
                follower.IsFollowing &&
                follower.Path.Count == 4;
            Debug.Assert(validPassed, "有効な経路の設定", this);
            Check(validPassed, "有効な経路の設定");

            sourcePath.Clear();

            bool copyPassed =
                follower.Path.Count == 4 &&
                !follower.TrySetPath(null) &&
                follower.Path.Count == 4;
            Debug.Assert(copyPassed, "経路の独立性と既存経路の維持", this);
            Check(copyPassed, "経路の独立性と既存経路の維持");
        }

        /// <summary>
        /// 基本的な経路追従動作を検証する。
        /// </summary>
        private void TestFollowing()
        {
            Prepare();

            int completedCount = 0;

            Vector2Int completedPosition = default;

            follower.PathCompleted += position =>
            {
                completedCount++;
                completedPosition = position;
            };

            bool setPassed =
                follower.TrySetPath(CreatePath());
            Debug.Assert(setPassed, "経路追従開始", this);
            Check(setPassed, "経路追従開始");

            bool destinationPassed =
                follower.Destination ==
                new Vector2Int(3, 2);
            Debug.Assert(destinationPassed, "目的地の取得", this);
            Check(destinationPassed, "目的地の取得");

            movement.Tick(1f);

            bool firstPassed =
                movement.CurrentCell ==
                    new Vector2Int(2, 1) &&
                follower.CurrentPathIndex == 1;
            Debug.Assert(firstPassed, "最初のセルへの到達", this);
            Check(firstPassed, "最初のセルへの到達");

            bool remainingPassed =
                follower.RemainingCellCount == 2 &&
                Mathf.Abs(
                    follower.Progress - 1f / 3f) < 0.0001f;
            Debug.Assert(remainingPassed, "残りセル数と進捗率", this);
            Check(remainingPassed, "残りセル数と進捗率");

            movement.Tick(1f);

            bool turnPassed =
                movement.CurrentCell ==
                    new Vector2Int(3, 1) &&
                movement.RequestedDirection ==
                    Vector2Int.up;
            Debug.Assert(turnPassed, "セル到達時の方向転換要求", this);
            Check(turnPassed, "セル到達時の方向転換要求");

            movement.Tick(1f);

            bool completePassed =
                follower.State ==
                    GridPathFollowerState.Completed &&
                movement.CurrentCell ==
                    new Vector2Int(3, 2) &&
                follower.Progress == 1f &&
                follower.RemainingCellCount == 0;
            Debug.Assert(completePassed, "目的地への到達", this);
            Check(completePassed, "目的地への到達");

            movement.Tick(3f);

            bool stopPassed =
                movement.CurrentCell ==
                    new Vector2Int(3, 2) &&
                !movement.IsMoving;
            Debug.Assert(stopPassed, "目的地での自動停止", this);
            Check(stopPassed, "目的地での自動停止");

            bool eventPassed =
                completedCount == 1 &&
                completedPosition ==
                    new Vector2Int(3, 2);
            Debug.Assert(eventPassed, "到達イベントの通知", this);
            Check(eventPassed, "到達イベントの通知");
        }

        /// <summary>
        /// 移動中の経路変更を検証する。
        /// </summary>
        private void TestPathReplacement()
        {
            Prepare();

            follower.TrySetPath(CreatePath());

            movement.Tick(0.5f);

            bool movingPassed =
                movement.IsTraversing &&
                movement.CurrentCell == startCell;
            Debug.Assert(movingPassed, "セル間の移動状態", this);
            Check(movingPassed, "セル間の移動状態");

            bool anchorPassed =
                follower.PathStartCell ==
                new Vector2Int(2, 1);
            Debug.Assert(anchorPassed, "移動中の探索開始位置", this);
            Check(anchorPassed, "移動中の探索開始位置");

            bool oldStartPassed =
                !follower.TrySetPath(CreatePath());
            Debug.Assert(oldStartPassed, "移動中の旧開始位置拒否", this);
            Check(oldStartPassed, "移動中の旧開始位置拒否");

            bool replacePassed =
                follower.TrySetPath(
                    new List<Vector2Int>
                    {
                        new Vector2Int(2, 1),
                        new Vector2Int(2, 2),
                        new Vector2Int(2, 3)
                    }) &&
                follower.CurrentPathIndex == -1;
            Debug.Assert(replacePassed, "移動中の経路変更", this);
            Check(replacePassed, "移動中の経路変更");

            movement.Tick(0.5f);

            bool reachedPassed =
                movement.CurrentCell ==
                    new Vector2Int(2, 1) &&
                follower.CurrentPathIndex == 0;
            Debug.Assert(reachedPassed, "移動区間の継続", this);
            Check(reachedPassed, "移動区間の継続");

            movement.Tick(2f);

            bool destinationPassed =
                follower.State ==
                    GridPathFollowerState.Completed &&
                movement.CurrentCell ==
                    new Vector2Int(2, 3);
            Debug.Assert(destinationPassed, "変更後の目的地到達", this);
            Check(destinationPassed, "変更後の目的地到達");
        }

        /// <summary>
        /// 一時停止と再開を検証する。
        /// </summary>
        private void TestPauseAndResume()
        {
            Prepare();

            follower.TrySetPath(CreatePath());

            movement.Tick(0.5f);

            Vector3 previousPosition =
                movement.transform.position;

            bool pausePassed =
                follower.Pause() &&
                follower.IsPaused &&
                movement.IsPaused;
            Debug.Assert(pausePassed, "経路追従の一時停止", this);
            Check(pausePassed, "経路追従の一時停止");

            movement.Tick(2f);

            bool positionPassed =
                Vector3.Distance(
                    movement.transform.position,
                    previousPosition) < 0.0001f;
            Debug.Assert(positionPassed, "停止中の座標維持", this);
            Check(positionPassed, "停止中の座標維持");

            bool setPassed =
                !follower.TrySetPath(CreatePath());
            Debug.Assert(setPassed, "停止中の経路変更拒否", this);
            Check(setPassed, "停止中の経路変更拒否");

            bool resumePassed =
                follower.Resume() &&
                follower.IsFollowing &&
                !movement.IsPaused;
            Debug.Assert(resumePassed, "経路追従の再開", this);
            Check(resumePassed, "経路追従の再開");

            movement.Tick(2.5f);

            bool completePassed =
                follower.State ==
                GridPathFollowerState.Completed;
            Debug.Assert(completePassed, "再開後の目的地到達", this);
            Check(completePassed, "再開後の目的地到達");

            bool invalidPassed =
                !follower.Pause() &&
                !follower.Resume();
            Debug.Assert(invalidPassed, "完了後の停止・再開拒否", this);
            Check(invalidPassed, "完了後の停止・再開拒否");
        }

        /// <summary>
        /// 経路追従の失敗検知を検証する。
        /// </summary>
        private void TestFailure()
        {
            Prepare();

            int failureCount = 0;

            GridPathFailureReason notifiedReason =
                GridPathFailureReason.None;

            follower.PathFailed += reason =>
            {
                failureCount++;
                notifiedReason = reason;
            };

            follower.TrySetPath(CreatePath());

            // 次の次のセルを通行不可能にする。
            blockedCells.Add(new Vector2Int(3, 1));

            movement.Tick(1f);

            bool blockedPassed =
                follower.State ==
                    GridPathFollowerState.Failed &&
                follower.LastFailureReason ==
                    GridPathFailureReason.CellBlocked;
            Debug.Assert(blockedPassed, "動的障害物の検知", this);
            Check(blockedPassed, "動的障害物の検知");

            movement.Tick(2f);

            bool stopPassed =
                movement.CurrentCell ==
                    new Vector2Int(2, 1) &&
                !movement.IsMoving;
            Debug.Assert(stopPassed, "障害検知後の停止", this);
            Check(stopPassed, "障害検知後の停止");

            bool eventPassed = failureCount == 1;
            Debug.Assert(eventPassed, "失敗イベントの通知", this);
            Check(eventPassed, "失敗イベントの通知");

            blockedCells.Clear();

            bool recoverPassed =
                follower.TrySetPath(
                    new List<Vector2Int>
                    {
                        new Vector2Int(2, 1),
                        new Vector2Int(2, 2)
                    }) &&
                follower.IsFollowing &&
                follower.LastFailureReason ==
                    GridPathFailureReason.None;
            Debug.Assert(recoverPassed, "失敗後の経路再設定", this);
            Check(recoverPassed, "失敗後の経路再設定");

            movement.Tick(0.25f);

            // テレポートの実行結果を取得する。
            bool teleportResult = movement.TryTeleport(
                new Vector2Int(5, 5));

            bool teleportPassed =
                follower.State ==
                    GridPathFollowerState.Failed &&
                follower.LastFailureReason ==
                    GridPathFailureReason.Teleported;
            Debug.Assert(teleportPassed, "外部座標変更の検知", this);
            Check(teleportPassed, "外部座標変更の検知");

            bool teleportEventPassed =
                notifiedReason ==
                GridPathFailureReason.Teleported;

            Debug.Assert(
                teleportEventPassed,
                "瞬間移動時の失敗通知理由",
                this);

            Check(
                teleportEventPassed,
                "瞬間移動時の失敗通知理由");


            bool teleportEventCountPassed =
                failureCount == 2;

            Debug.Assert(
                teleportEventCountPassed,
                "瞬間移動時の重複失敗通知防止",
                this);

            Check(
                teleportEventCountPassed,
                "瞬間移動時の重複失敗通知防止");


            bool teleportStateResetPassed =
                !movement.IsTeleporting;

            Debug.Assert(
                teleportStateResetPassed,
                "瞬間移動処理状態の解除",
                this);

            Check(
                teleportStateResetPassed,
                "瞬間移動処理状態の解除");

            Prepare();

            follower.TrySetPath(CreatePath());

            movement.Tick(0.5f);

            movement.StopImmediately();

            bool externalStopPassed =
                follower.State ==
                    GridPathFollowerState.Failed &&
                follower.LastFailureReason ==
                    GridPathFailureReason.MovementStopped;
            Debug.Assert(externalStopPassed, "外部移動停止の検知", this);
            Check(externalStopPassed, "外部移動停止の検知");
        }

        /// <summary>
        /// 中断、初期化、解放処理を検証する。
        /// </summary>
        private void TestLifecycle()
        {
            Prepare();

            int cancelledCount = 0;

            follower.PathCancelled += () =>
            {
                cancelledCount++;
            };

            follower.TrySetPath(CreatePath());

            movement.Tick(0.5f);

            bool cancelPassed =
                follower.Cancel() &&
                follower.State ==
                    GridPathFollowerState.Cancelled;
            Debug.Assert(cancelPassed, "経路追従の中断", this);
            Check(cancelPassed, "経路追従の中断");

            movement.Tick(3f);

            bool safeStopPassed =
                movement.CurrentCell ==
                    new Vector2Int(2, 1) &&
                !movement.IsMoving;
            Debug.Assert(safeStopPassed, "中断後のセル中心停止", this);
            Check(safeStopPassed, "中断後のセル中心停止");

            bool eventPassed =
                cancelledCount == 1 &&
                !follower.Cancel();
            Debug.Assert(eventPassed, "中断イベントと重複中断防止", this);
            Check(eventPassed, "中断イベントと重複中断防止");

            bool resetPassed =
                follower.Reset() &&
                follower.State ==
                    GridPathFollowerState.Idle &&
                !follower.HasPath &&
                follower.CurrentPathIndex == -1;
            Debug.Assert(resetPassed, "経路状態の初期化", this);
            Check(resetPassed, "経路状態の初期化");

            bool restartPassed =
                follower.TrySetPath(
                    new List<Vector2Int>
                    {
                        new Vector2Int(2, 1),
                        new Vector2Int(3, 1)
                    });
            Debug.Assert(restartPassed, "初期化後の経路設定", this);
            Check(restartPassed, "初期化後の経路設定");

            follower.Dispose();

            bool disposePassed =
                follower.IsDisposed &&
                !follower.HasPath &&
                movement.IsInitialized;
            Debug.Assert(disposePassed, "解放と移動制御の維持", this);
            Check(disposePassed, "解放と移動制御の維持");

            bool invalidPassed =
                !follower.TrySetPath(CreatePath()) &&
                !follower.Pause() &&
                !follower.Resume() &&
                !follower.Cancel() &&
                !follower.Reset();
            Debug.Assert(invalidPassed, "解放後の操作拒否", this);
            Check(invalidPassed, "解放後の操作拒否");

            follower.Dispose();

            movement.TryTeleport(startCell);

            movement.RequestDirection(Vector2Int.up);

            movement.Tick(1f);

            bool unsubscribePassed =
                follower.IsDisposed &&
                movement.CurrentCell ==
                    new Vector2Int(1, 2);
            Debug.Assert(unsubscribePassed, "購読解除と移動制御の再利用", this);
            Check(unsubscribePassed, "購読解除と移動制御の再利用");
        }

        /// <summary>
        /// テスト用リソースを解放する。
        /// </summary>
        private void Cleanup()
        {
            follower?.Dispose();

            follower = null;

            if (movementObject != null)
            {
                movementObject.SetActive(false);

                Destroy(movementObject);

                movementObject = null;
            }

            if (gridObject != null)
            {
                gridObject.SetActive(false);

                Destroy(gridObject);

                gridObject = null;
            }

            movement = null;
            converter = null;

            blockedCells.Clear();
        }

        /// <summary>
        /// 個別のテスト結果を出力して集計する。
        /// </summary>
        /// <param name="passed">成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
